// The paste matte's edge falloff, as the render computes it - the maths behind the mask micro-profile beside the feather and
// erode sliders. No React, no DOM: `.render-check/mask-edge-check.mjs` runs it under node and compares it, sample for sample,
// against `roop.mask_composer.MaskComposer.asymmetric_inward` (fixture generated by gen-mask-edge-fixture.py from the REAL
// class, not from this file's reading of it).
//
// WHAT IS MODELLED. The default paste (`semantic_paste_mask: true`, and the hull fallback inside it) builds its alpha in
// `procmgr_masking.paste_upscale` and hands it to `MaskComposer.asymmetric_inward`:
//
//     feather  = max(1, min(h, w) * face_mask_blend / 200)           h, w = the PASTED CROP, so feather is a fraction of it
//     dist(x)  = DT_STEP * (inward pixels from the matte boundary): `cv2.distanceTransform(..., DIST_L2, 3)` is a 3x3 chamfer
//                with 0.955 per orthogonal step, not 1, so the ramp spans width / 0.955 pixels (+4.7%). A distance transform
//                gives the ramp the same width around the whole contour - it does not narrow at a convex corner the way a
//                blurred mask does
//     width    = max(min(feather * (1 + 0.6 s f - 0.4 s n), 0.18 * span), 1)         (yaw 0: s = 0, so width = feather)
//     alpha(x) = smoothstep(clip((dist(x) - 0.04 span s f^2) / width, 0, 1))          t^2 (3 - 2t)
//
//     s = min(|yaw| / 60, 1); f, n = 0..1 lateral ramps that are 1 at the FAR / NEAR extreme of the face (see lateralFactors);
//     span = min(width, height) of the matte's support.
//
// `mask_erode_dilate_radius` moves the matte boundary before this runs (`create_landmark_mask`, in crop px): +r grows the hull
// outward, -r shrinks it. On a straight edge that is a pure shift of the whole ramp by r, which is what `buildProfile` draws.
//
// WHAT IS NOT. `semantic_paste_mask: false` falls back to the legacy erode + Gaussian (`blur_area`), whose width depends on the
// matte's bounding box in a space this model does not see - `isModelled` says so and the component draws no curve rather than a
// wrong one. The crop size and the matte span are not known to the browser: `DEFAULT_CROP_PX` and `DEFAULT_SPAN_FRAC` are
// stated assumptions, shown to the user, and only the 18% cap depends on the span.

export const COMPOSER = Object.freeze({ farInsetFrac: 0.04, farSoften: 0.6, nearTighten: 0.4, featherCap: 0.18, yawFullDeg: 60 });
/** OpenCV's 3x3 L2 chamfer weight for a horizontal / vertical step (the diagonal is 1.3693; a straight edge never uses it). */
export const DT_STEP = 0.955;
export const DEFAULT_CROP_PX = 512;
/** The matte's smaller side over the crop's: a face fills most of an aligned crop. Only the 18% cap reads it. */
export const DEFAULT_SPAN_FRAC = 0.8;

const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
export const smoothstep = (t) => { const c = clamp(t, 0, 1); return c * c * (3 - 2 * c); };

/** `paste_upscale`: `_feather = max(1., min(h,w) * mask_offsets[4] / 200.)`. */
export const pasteFeatherPx = (blend, cropPx = DEFAULT_CROP_PX) => {
  const b = Number(blend);
  return Math.max(1, cropPx * (Number.isFinite(b) ? b : 0) / 200);
};

export const yawStrength = (yawDeg) => Math.min(Math.abs(Number(yawDeg) || 0) / COMPOSER.yawFullDeg, 1);

/**
 * The lateral ramps at a column `rel` (0 = left edge of the matte, 1 = right edge). Positive yaw turns the face so the +x cheek
 * is the FAR one. f is 0 up to the centre and 1 at the far extreme; n is 1 at the near extreme and 0 from the centre on.
 */
export function lateralFactors(rel, yawDeg) {
  const far = yawDeg > 0 ? rel : 1 - rel;
  return { f: clamp(2 * far - 1, 0, 1), n: clamp(1 - 2 * far, 0, 1) };
}

/** The ramp width at a point of the contour, after the yaw terms and the 18%-of-span cap (and never under 1 px). */
export function rampWidthPx(featherPx, spanPx, s = 0, f = 0, n = 0) {
  const raw = s > 0 ? featherPx * (1 + COMPOSER.farSoften * s * f - COMPOSER.nearTighten * s * n) : featherPx;
  return Math.max(Math.min(raw, COMPOSER.featherCap * spanPx), 1);
}

/** How far the FAR edge is pulled inward at this point. */
export const farInsetPx = (spanPx, s = 0, f = 0) => COMPOSER.farInsetFrac * spanPx * s * f * f;

/** alpha at an inward distance `dist` (px from the matte boundary; 0 outside it). */
export function edgeAlpha(dist, widthPx, insetPx = 0) {
  return smoothstep(Math.max(dist - insetPx, 0) / widthPx);
}

/** The inverse of smoothstep by bisection: the t whose alpha is `a`. */
export function smoothstepInverse(a) {
  let lo = 0; let hi = 1;
  for (let i = 0; i < 40; i += 1) { const mid = (lo + hi) / 2; if (smoothstep(mid) < a) lo = mid; else hi = mid; }
  return (lo + hi) / 2;
}

/** Whether the live matte is one this module models (the semantic paste), as opposed to the legacy Gaussian. */
export const isModelled = (settings) => (settings?.semantic_paste_mask ?? true) !== false;

/**
 * One cross-section of the matte edge, ready to draw. `x` is crop px measured OUTWARD from the detected hull boundary (so the
 * erode / dilate radius is where the alpha reaches 0), `alpha` 0..1 in the same order.
 *
 * Three curves: the frontal one (the default), and the far / near extremes of a 60-degree turned face - the part of the
 * composer that makes one slider soft on one cheek and tight on the other.
 */
export function buildProfile({ blend, erode = 0, cropPx = DEFAULT_CROP_PX, spanFrac = DEFAULT_SPAN_FRAC, yawDeg = 60, samples = 96 } = {}) {
  const feather = pasteFeatherPx(blend, cropPx);
  const span = Math.max(1, cropPx * spanFrac);
  const radius = Number.isFinite(Number(erode)) ? Number(erode) : 0;
  const s = yawStrength(yawDeg);

  const curves = {
    front: { width: rampWidthPx(feather, span), inset: 0 },
    far: { width: rampWidthPx(feather, span, s, 1, 0), inset: farInsetPx(span, s, 1) },
    near: { width: rampWidthPx(feather, span, s, 0, 1), inset: 0 },
  };
  const reach = Math.max(curves.front.width, curves.far.width + curves.far.inset, curves.near.width, 4) / DT_STEP;
  const lo = -(reach * 1.15 + Math.max(0, -radius));
  const hi = Math.max(reach * 0.35, radius + reach * 0.2, 4);
  const x = [];
  for (let i = 0; i < samples; i += 1) x.push(lo + ((hi - lo) * i) / (samples - 1));

  // x is outward px; the matte is inside where radius - x > 0, and there the distance transform reads DT_STEP per pixel.
  const alphaOf = (c) => x.map((px) => (radius - px > 0 ? edgeAlpha(DT_STEP * (radius - px), c.width, c.inset) : 0));
  const t10 = smoothstepInverse(0.1); const t90 = smoothstepInverse(0.9);
  const frontWidth = curves.front.width;
  const frontPx = frontWidth / DT_STEP;                 // the ramp's extent in pixels
  return {
    x, lo, hi,
    alpha: alphaOf(curves.front),
    far: alphaOf(curves.far),
    near: alphaOf(curves.near),
    featherPx: feather,
    widthPx: frontPx,
    capped: frontWidth < feather - 1e-9,                   // the 18%-of-span cap is shorter than the slider asked for
    /** where the frontal alpha crosses 50%: outward distance from the detected boundary */
    midPx: radius - 0.5 * frontPx,
    /** the 10%-90% width: how wide the visible transition really is */
    width1090Px: (t90 - t10) * frontPx,
    /** the steepest part of the ramp, in alpha per px (smoothstep's maximum slope is 1.5 at its centre) */
    maxSlopePerPx: (1.5 * DT_STEP) / frontWidth,
    radiusPx: radius,
    cropPx, spanFrac, yawDeg,
  };
}
